require_once 'sidebar.php';
require_once '../conexao.php';require_once '../includes/rbac.php';require_once '../includes/flash.php';exigirCargo(['diretor','administrador']);
$usuarios=$pdo->query("SELECT u.id,u.nome,u.email,u.cargo,u.ativo,u.criado_em,u.cpf,u.telefone,u.nascimento,u.endereco,u.data_admissao,u.excluido_em,p.nome profissional,p.especialidade,GROUP_CONCAT(up.permissao ORDER BY up.permissao SEPARATOR ', ') permissoes FROM usuarios u LEFT JOIN profissionais p ON p.id=u.profissional_id LEFT JOIN usuario_permissoes up ON up.usuario_id=u.id GROUP BY u.id ORDER BY u.cargo,u.nome")->fetchAll();
$profissionais=$pdo->query("SELECT p.id,p.nome,p.especialidade,p.ativo,COUNT(DISTINCT a.id) consultas,COUNT(DISTINCT d.id) disponibilidades FROM profissionais p LEFT JOIN agendamentos a ON a.profissional_id=p.id LEFT JOIN disponibilidades d ON d.profissional_id=p.id GROUP BY p.id ORDER BY p.nome")->fetchAll();
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Funcionários | Diretoria Aura</title><link rel="icon" type="image/png" sizes="512x512" href="../img/favicon-aura.png"><link rel="shortcut icon" href="../img/favicon.ico"><link rel="stylesheet" href="../css/style.css"></head><body class="director-page"><div class="app-shell director-shell"><?php renderDiretorSidebar('funcionarios'); ?><main class="dashboard director-subpage"><div class="dash-head"><div><p class="eyebrow">ADMINISTRADOR TOTAL</p><h1>Funcionários e acessos</h1><p class="muted">Visão consolidada de contas, cargos, vínculos e permissões. Senhas nunca são exibidas.</p></div></div><section class="dash-card"><h2>Usuários internos</h2><div class="table-wrapper flat"><table><thead><tr><th>Nome</th><th>Login</th><th>CPF</th><th>Telefone</th><th>Nascimento</th><th>Endereço</th><th>Admissão</th><th>Cargo</th><th>Profissional vinculado</th><th>Especialidade</th><th>Permissões</th><th>Status</th><th>Criado em</th></tr></thead><tbody><?php foreach($usuarios as $u):?><tr><td><?=htmlspecialchars($u['nome'])?></td><td><?=htmlspecialchars($u['email'])?></td><td><?=htmlspecialchars($u['cpf']?:'—')?></td><td><?=htmlspecialchars($u['telefone']?:'—')?></td><td><?=$u['nascimento']?date('d/m/Y',strtotime($u['nascimento'])):'—'?></td><td><?=htmlspecialchars($u['endereco']?:'—')?></td><td><?=$u['data_admissao']?date('d/m/Y',strtotime($u['data_admissao'])):'—'?></td><td><?=htmlspecialchars(ucfirst($u['cargo']))?></td><td><?=htmlspecialchars($u['profissional']??'—')?></td><td><?=htmlspecialchars($u['especialidade']??'—')?></td><td><?=htmlspecialchars($u['permissoes']?:($u['cargo']==='diretor'?'Acesso total':'—'))?></td><td><span class="badge"><?=$u['ativo']?'Ativo':'Inativo'?></span></td><td><?=date('d/m/Y H:i',strtotime($u['criado_em']))?></td></tr><?php endforeach;?></tbody></table></div></section><section class="dash-card" style="margin-top:20px"><h2>Profissionais cadastrados</h2><div class="table-wrapper flat"><table><thead><tr><th>Nome</th><th>Especialidade</th><th>Consultas registradas</th><th>Horários específicos</th><th>Status</th></tr></thead><tbody><?php foreach($profissionais as $p):?><tr><td><?=htmlspecialchars($p['nome'])?></td><td><?=htmlspecialchars($p['especialidade'])?></td><td><?=$p['consultas']?></td><td><?=$p['disponibilidades']?></td><td><span class="badge"><?=$p['ativo']?'Ativo':'Inativo'?></span></td></tr><?php endforeach;?></tbody></table></div></section></main></div><script src="../js/app.js"></script></body></html>
